INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES ("", "vo_minigame_1013_top_talk_6_001", "", "vo_minigame_1013", 0, 6, "", "", 0, 21, 6010);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (0, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 0, 129911, 6, 6, 0.8, 0, 1, 11, 6011);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES ("", "", "", 0, "", 6, "", "", "", 91, 6012);
