INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (0, "エリコ班の急成長は\n騎士団の中でも話題に\nなってたからな\nホントすげえ奴等だよ", 0, 129811, 6, 7, 0, 0, 1, 11, 7011);
